mapper.sql:
where 1=1

		and cmsj_llave = #{llaveTabla}


		and cmsj_estado = #{estado}


		and dmsj_fecha >= #{fechaMin}


		and dmsj_fecha  <   #{fechaMax}


		and cmsj_titulo = #{titulo}


		and cmsj_usuario = #{usuario}


		and cmsj_documento = #{documento}


		and cmsj_template = #{template}


		and dmsj_leido >= #{leidoMin}


		and dmsj_leido  <   #{leidoMax}


		and dmsj_correoenviado >= #{correoEnviadoMin}


		and dmsj_correoenviado  <   #{correoEnviadoMax}


		and cmsj_reporte = #{reporte}
